"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[9009],{29009:e=>{e.exports=JSON.parse('{"slug":"zanyatost-ssha-sentyabr-realnye-zarplaty","locale":"es","title":"Estados Unidos crea 3 veces menos empleo del previsto y los sueldos pierden frente a los precios","description":"Septiembre aporta 29 mil empleos frente a 90 mil previstos; salarios +3% e inflaci\xf3n del 3,4%. Qu\xe9 es el sueldo real y qu\xe9 implica para la Fed.","blocks":[{"id":"b001","kind":"paragraph","text":"Trabajo inform\xf3 el 2 de octubre de 2026 de 29 mil empleos creados en septiembre, frente a unos 90 mil previstos. Julio y agosto se revisaron a la baja en 60 mil. El paro pas\xf3 del 4,1% al 4,2%. Salud a\xf1adi\xf3 17 mil empleos y construcci\xf3n 11 mil; finanzas perdi\xf3 7 mil."},{"id":"b002","kind":"paragraph","text":"Los salarios son lo m\xe1s d\xe9bil del informe. El ingreso horario subi\xf3 solo un 0,1% mensual, m\xednimo desde diciembre de 2025. El crecimiento anual fue del 3%, el menor desde mayo de 2021. Los precios crecen un 3,4%, seg\xfan agosto: el sueldo permite comprar menos que hace un a\xf1o."},{"id":"b003","kind":"paragraph","text":"Esa es la diferencia entre sueldo nominal y real. El nominal es lo que figura en n\xf3mina; el real mide lo que compra, ajustando el aumento por los precios. Comparando sueldo de septiembre con inflaci\xf3n de agosto, cae alrededor del 0,4% anual (1,03 / 1,034). En Rusia, el salario medio de julio de 2026 creci\xf3 un 9,5%, a 109,5 mil rublos, y el real un 3,3%. Es una comparaci\xf3n aproximada por meses y m\xe9todos distintos. Tambi\xe9n se fren\xf3 Rusia: junio hab\xeda registrado un 3,4% real."},{"id":"b004","kind":"paragraph","text":"Un mercado laboral d\xe9bil invita a la Fed a esperar. En una semana, la probabilidad de subir el 27–28 de octubre baj\xf3 del 64% a cerca del 20%, primero por inflaci\xf3n y despu\xe9s por empleo. Pero el 3,4% sigue sobre la meta del 2%. Se espera aplazar, no cancelar: grandes bancos como Goldman Sachs a\xfan prev\xe9n diciembre. El bono a 10 a\xf1os baj\xf3 inicialmente tras el dato, pero termin\xf3 cerca del 5,28%. El tipo actual de la Fed es del 3,75–4%."},{"id":"b005","kind":"paragraph","text":"El informe llega al lector ruso por un d\xf3lar con fuerzas opuestas. Aplazar la subida le resta atractivo y el lunes 5 de octubre cedi\xf3 algo frente a otras monedas. Pero los bonos siguen pagando m\xe1s del 5%, sosteniendo la demanda. En Rusia pesan m\xe1s petr\xf3leo y Banco de Rusia. El siguiente informe estadounidense saldr\xe1 el 6 de noviembre, despu\xe9s de la reuni\xf3n de octubre."},{"id":"b006","kind":"paragraph","text":"Vender d\xf3lares tras un dato d\xe9bil apuesta a que la Fed abandonar\xe1 las subidas, algo no prometido. Comprar esperando apreciaci\xf3n tambi\xe9n tiene riesgo: m\xe1s desempleo podr\xeda eliminar incluso la subida de diciembre. No se sabe si la debilidad laboral ser\xe1 tendencia."},{"id":"b007","kind":"heading","text":"\xbfCu\xe1ntos empleos cre\xf3 Estados Unidos en septiembre de 2026?"},{"id":"b008","kind":"paragraph","text":"29 mil frente a unos 90 mil previstos. Julio y agosto se revisaron en 60 mil menos y el paro pas\xf3 del 4,1% al 4,2%."},{"id":"b009","kind":"heading","text":"\xbfQu\xe9 es el salario real?"},{"id":"b010","kind":"paragraph","text":"El sueldo ajustado por precios: cu\xe1nto permite comprar. En Estados Unidos creci\xf3 un 3% con inflaci\xf3n del 3,4%, por lo que el real cae cerca del 0,4%. En Rusia, julio registr\xf3 un aumento real del 3,3%."},{"id":"b011","kind":"heading","text":"\xbfSubir\xe1 la Fed despu\xe9s del informe d\xe9bil?"},{"id":"b012","kind":"paragraph","text":"En octubre parece poco probable: el mercado asigna cerca del 20%, frente al 64% de la semana anterior. A\xfan espera diciembre junto con los grandes bancos. El tipo actual es del 3,75–4%."}],"sources":[{"label":"El empleo de septiembre decepciona: solo 29,000 puestos y m\xe1s paro","url":"https://finance.yahoo.com/economy/article/septembers-jobs-report-shows-the-us-added-just-29000-jobs-and-unemployment-ticked-up-195320409.html"},{"label":"La inflaci\xf3n lleva meses absorbiendo mejoras salariales; septiembre no cambia","url":"https://finance.yahoo.com/economy/article/inflation-has-been-eating-up-wage-gains-for-months-september-was-no-better-180727718.html"},{"label":"Econom\xeda mundial: Estados Unidos frena contrataci\xf3n y salarios","url":"https://www.bloomberg.com/news/articles/2026-10-03/world-economy-latest-us-employers-dial-back-hiring-wage-growth-slows"},{"label":"Nasdaq suma 319 puntos al bajar las opciones de subida de tipos","url":"https://www.kiplinger.com/investing/stocks/nasdaq-adds-319-points-as-rate-hike-odds-ebb-stock-market-today"},{"label":"Se desvanece la subida de octubre: qu\xe9 significa el informe de 29K empleos","url":"https://www.fxstreet.com/analysis/the-october-fed-hike-just-died-heres-what-the-29k-jobs-report-really-means-for-rates-202610021806"},{"label":"Los bonos bajan tras el dato laboral que reduce las opciones de subida","url":"https://www.indexbox.io/blog/treasury-yields-fall-after-weak-september-jobs-report-cuts-odds-of-october-fed-rate-hike/"},{"label":"Las bolsas avanzan y el d\xf3lar vacila al reducirse las apuestas de subida","url":"https://www.investing.com/news/economy-news/stocks-upbeat-dollar-wobbles-as-fed-hike-bets-recede-4930982"},{"label":"Calendario de publicaci\xf3n del informe de empleo","url":"https://www.bls.gov/schedule/news_release/empsit.htm"},{"label":"El salario real ruso de julio se frena al 3,3% interanual","url":"https://ru.themoscowtimes.com/2026/09/30/rost-realnykh-zarplat-v-rf-v-iyule-26g-zamedlilsya-do-33-gg-a207452"}],"sourceBodySha256":"8dbaae3cc9570f53146a348a9d62855bcdad77232b7be2422c1b98c268553b25"}')}}]);